create or replace function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=(select auth.uid()) and role='admin')$$;
create or replace function public.in_booking(bid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.bookings where id=bid and (parent_id=(select auth.uid()) or sitter_id=(select auth.uid())))$$;
alter table public.profiles enable row level security;alter table public.sitter_profiles enable row level security;alter table public.pets enable row level security;alter table public.services enable row level security;alter table public.bookings enable row level security;alter table public.availability enable row level security;alter table public.booking_updates enable row level security;alter table public.messages enable row level security;alter table public.reviews enable row level security;alter table public.payments enable row level security;
revoke all on all tables in schema public from anon,authenticated;grant select on public.services,public.sitter_profiles to anon,authenticated;grant select,update on public.profiles to authenticated;grant select,insert,update,delete on public.pets,public.bookings,public.availability,public.booking_updates,public.messages,public.reviews to authenticated;grant select on public.payments to authenticated;grant all on all tables in schema public to service_role;
create policy profiles_read on public.profiles for select to authenticated using(id=(select auth.uid()) or role='sitter' or public.is_admin());
create policy profiles_update_self on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy sitter_public_read on public.sitter_profiles for select to anon,authenticated using(verified or user_id=(select auth.uid()) or public.is_admin());
create policy pets_owner_read on public.pets for select to authenticated using(parent_id=(select auth.uid()) or public.is_admin() or exists(select 1 from public.bookings b where b.pet_id=id and b.sitter_id=(select auth.uid())));
create policy pets_owner_insert on public.pets for insert to authenticated with check(parent_id=(select auth.uid()) or public.is_admin());create policy pets_owner_update on public.pets for update to authenticated using(parent_id=(select auth.uid()) or public.is_admin()) with check(parent_id=(select auth.uid()) or public.is_admin());create policy pets_owner_delete on public.pets for delete to authenticated using(parent_id=(select auth.uid()) or public.is_admin());
create policy services_public_read on public.services for select to anon,authenticated using(active or public.is_admin());
create policy bookings_participant_read on public.bookings for select to authenticated using(parent_id=(select auth.uid()) or sitter_id=(select auth.uid()) or public.is_admin());
create policy bookings_parent_insert on public.bookings for insert to authenticated with check(parent_id=(select auth.uid()) or public.is_admin());create policy bookings_participant_update on public.bookings for update to authenticated using(parent_id=(select auth.uid()) or sitter_id=(select auth.uid()) or public.is_admin());
create policy availability_read on public.availability for select to authenticated using(true);create policy availability_sitter_insert on public.availability for insert to authenticated with check(sitter_id=(select auth.uid()) or public.is_admin());create policy availability_sitter_update on public.availability for update to authenticated using(sitter_id=(select auth.uid()) or public.is_admin());create policy availability_sitter_delete on public.availability for delete to authenticated using(sitter_id=(select auth.uid()) or public.is_admin());
create policy updates_participant_read on public.booking_updates for select to authenticated using(public.in_booking(booking_id) or public.is_admin());create policy updates_author_insert on public.booking_updates for insert to authenticated with check(author_id=(select auth.uid()) and public.in_booking(booking_id));
create policy messages_participant_read on public.messages for select to authenticated using(sender_id=(select auth.uid()) or recipient_id=(select auth.uid()) or public.is_admin());create policy messages_sender_insert on public.messages for insert to authenticated with check(sender_id=(select auth.uid()) and public.in_booking(booking_id));create policy messages_recipient_update on public.messages for update to authenticated using(recipient_id=(select auth.uid()) or public.is_admin());
create policy reviews_public_read on public.reviews for select to authenticated using(true);create policy reviews_parent_insert on public.reviews for insert to authenticated with check(parent_id=(select auth.uid()) or public.is_admin());
create policy payments_participant_read on public.payments for select to authenticated using(public.is_admin() or exists(select 1 from public.bookings b where b.id=booking_id and (b.parent_id=(select auth.uid()) or b.sitter_id=(select auth.uid()))));
